begin
    t ← 0;
    u ← trạng thái ban đầu nào đó;
    T ← nhiệt độ ban đầu;
    repeat
        v ← trạng thái được chọn nhẫu nhiên trong lân cận u;
        if $cost(v) > cost(u)$ then u ← v
        else u ← v với xác suất $e^{\Delta/T}$;
