Giải thuật Minimax
Function MaxVal(u);
begin
    if u là đình kết thúc then MinVal(u) ← f(u)
        else MinVal(u) ← min{MaxVal(v) | v là đình con của u}
end;
Function MinVal(u);
begin
    if u là đình kết thúc then MaxVal(u) ← f(u)
        else MaxVal(u) ← max{MinVal(v) | v là đình con của u}
end;
Procedure Minimax(u, v);
begin
    val ← -∞;
    for mỗi w là đình con của u do
        if val(u) <= MinVal(w) then
            {val ← MinVal(w); v ← w}
end;
